// Icone rend le tracé d'une icône. Le viewBox est celui de Font Awesome, qui
// varie d'une icône à l'autre : le forcer casserait les proportions.
func Icone(cle string) template.HTML {
	i, ok := icones[cle]
	if !ok {
		return ""
	}
	return template.HTML(`<svg class="ico" viewBox="` + i.vb + `" aria-hidden="true" ` +
		`focusable="false" fill="currentColor"><path d="` + i.d + `"/></svg>`)
}
